import{_ as s,o as a,c as t,a6 as n}from"./chunks/framework.DMOj2-2K.js";const i="/diagrams/layers.svg",g=JSON.parse('{"title":"Project structure & layers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/structure.md","filePath":"guide/structure.md"}'),r={name:"guide/structure.md"};function l(p,e,o,d,c,h){return a(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="project-structure-layers" tabindex="-1">Project structure &amp; layers <a class="header-anchor" href="#project-structure-layers" aria-label="Permalink to &quot;Project structure &amp; layers&quot;">​</a></h1><p>Every Cluub project has the <strong>same shape</strong>. The compiler enforces it (error <strong>E301</strong>), so anyone (a teammate, a reviewer, an AI) knows where everything is.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>├── app.clb            # name, port, AI provider</span></span>
<span class="line"><span>├── models/              # data shapes + validation rules</span></span>
<span class="line"><span>├── data/                # stores: where models are saved      (data layer)</span></span>
<span class="line"><span>├── network/             # clients: outside APIs               (network layer)</span></span>
<span class="line"><span>├── services/            # business logic and AI</span></span>
<span class="line"><span>├── api/                 # HTTP endpoints over services</span></span>
<span class="line"><span>├── ui/</span></span>
<span class="line"><span>│   ├── pages/           # screens with state and actions      (UI layer)</span></span>
<span class="line"><span>│   ├── components/      # reusable display pieces</span></span>
<span class="line"><span>│   └── layouts/         # header/footer around pages</span></span>
<span class="line"><span>├── tests/               # your tests</span></span>
<span class="line"><span>│   └── generated/       # tests Cluub writes (rewritten on every \`cluub test\`)</span></span>
<span class="line"><span>├── .env                 # secrets (never committed)</span></span>
<span class="line"><span>└── theme.css            # optional: override colors and fonts</span></span></code></pre></div><h2 id="the-layer-rule" tabindex="-1">The layer rule <a class="header-anchor" href="#the-layer-rule" aria-label="Permalink to &quot;The layer rule&quot;">​</a></h2><p><img src="`+i+`" alt="Cluub layers: page uses api, api uses service, service uses store, client and AI"></p><table tabindex="0"><thead><tr><th>A…</th><th>may use…</th><th>because</th></tr></thead><tbody><tr><td>page</td><td>apis</td><td>the browser only talks to the server through HTTP</td></tr><tr><td>api</td><td>services</td><td>endpoints stay thin; logic is reusable and testable</td></tr><tr><td>service</td><td>stores, clients, other services, AI</td><td>this is where decisions live</td></tr><tr><td>component, layout</td><td>nothing (data comes in via <code>takes</code>)</td><td>easy to reuse and to test</td></tr></tbody></table><p>Break the rule and you get a clear error:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span>error E201 ui/pages/shop.clb:9:13</span></span>
<span class="line"><span>  A UI page (Shop) can&#39;t use the data layer directly (Products is a store).</span></span>
<span class="line"><span>   9 |     items = Products.all()</span></span>
<span class="line"><span>     |             ^^^^^^^^</span></span>
<span class="line"><span>  hint: Pages talk to the backend only through an \`api\`. Flow: page → api → service → store/client.</span></span></code></pre></div><h2 id="declaring-dependencies" tabindex="-1">Declaring dependencies <a class="header-anchor" href="#declaring-dependencies" aria-label="Permalink to &quot;Declaring dependencies&quot;">​</a></h2><p>Every dependency is named with <code>uses</code>. That is <strong>dependency injection</strong>: Cluub builds each service with exactly what it asked for, and tests replace stores with empty in-memory ones and the AI with a fake.</p><div class="language-cluub vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cluub</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">service</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> InvoiceService</span></span>
<span class="line"><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">  uses</span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;"> Invoices</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">Customers</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">PaymentsGateway</span></span></code></pre></div><p>Using something you didn&#39;t declare is error <strong>E106</strong>; declaring something you don&#39;t use is warning <strong>W101</strong>.</p><h2 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h2><ul><li>Declarations: <code>PascalCase</code> (<code>TodoService</code>, <code>Home</code>). Error <strong>E102</strong>.</li><li>Everything else: <code>camelCase</code> (<code>dueDate</code>, <code>markDone</code>). Error <strong>E103</strong>.</li><li>File names are up to you; the convention is kebab-case (<code>todo-service.clb</code>).</li></ul>`,14)])])}const y=s(r,[["render",l]]);export{g as __pageData,y as default};
